        if path.extension() == Some("toml".as_ref()) {
            let pack = FancyPack::parse(path).map_err(LookupError::FancyPackParseFailed)?;
            Ok(Pack::Fancy(pack))
        } else {
            Ok(Pack::Simple(path))
