    #[cfg(not(test))]
    {
        // Not-found is the ordinary first-write case, so the delete's verdict is discarded; a
        // delete that fails for any other reason surfaces on the add below.
        let _ = delete_generic_password(SERVICE, account);

        let control = SecAccessControl::create_with_protection(
            Some(ProtectionMode::AccessibleAfterFirstUnlock),
            0,
        )
        .map_err(KeychainError::Security)?;
        let mut options = PasswordOptions::new_generic_password(SERVICE, account);
        options.set_access_control(control);
        set_generic_password_options(data, options).map_err(KeychainError::Security)
    }
}

/// Delete an item from the **device-local** Keychain store by account name.
///
/// Returns `Ok(())` on successful deletion, or `Err` if the item doesn't exist.
pub fn delete_item(account: &str) -> Result<(), KeychainError> {
    #[cfg(test)]
    {
        test_store::delete(test_store::Scope::Local, account);
        Ok(())
    }
    #[cfg(not(test))]
    delete_generic_password(SERVICE, account).map_err(KeychainError::Security)
}

/// `errSecItemNotFound` — the Security framework's "no such item" status.
///
/// Callers that hold a raw `security_framework` error rather than a `KeychainError`
/// (a direct `ItemSearchOptions` query, for instance) compare against this instead of
/// re-spelling the magic number.
pub const ERR_SEC_ITEM_NOT_FOUND: i32 = -25300;

/// Returns true if the error is errSecItemNotFound (OS status -25300).
/// Use this to distinguish "item does not exist" from transient OS errors.
pub fn is_not_found(err: &KeychainError) -> bool {
    match err {
        KeychainError::Security(e) => e.code() == ERR_SEC_ITEM_NOT_FOUND,
        // Not an absence claim — the account was never addressed.
        KeychainError::SyncNotPermitted { .. } => false,
        #[cfg(test)]
        KeychainError::NotFound => true,
    }
}

// ── OAuth Keychain helpers ─────────────────────────────────────────────────────

const DPOP_KEY_PRIV_ACCOUNT: &str = "oauth-dpop-key-priv";
const OAUTH_ACCESS_TOKEN_ACCOUNT: &str = "oauth-access-token";

input.content:
// The pure half of the Notification Service Extension: everything that turns bytes into
// other bytes, with no Keychain, no CryptoKit, and no UserNotifications.
//
// It lives apart from NotificationService.swift for the same reason the wallet's Rust keeps
// `_impl` cores away from Tauri commands — this is the part an XCTest can drive on a
// simulator, and the part the Rust↔CryptoKit fixture cross-check exercises.

import Foundation

/// The `ezpds` object a sealed push carries beside its placeholder `aps` alert.
///
/// Wire shape (see `crates/notify-relay/src/protocol.rs`):
/// `{ "v": 1, "kid": 3, "enc": "<b64url>", "ct": "<b64url>" }`
struct NotifyEnvelope: Equatable {
    /// Protocol version. Only `1` is understood; anything else is a payload sealed by a
    /// newer instance for a newer extension, and must render as unverified rather than be
    /// guessed at.
    static let supportedVersion = 1

    let version: Int
    /// The instance-scoped sender-key id. Not a global identifier: two Custos instances both
    /// start their `kid` sequence at 1, which is why the pin store is keyed by host and every
    /// candidate under this id is tried.
    let kid: Int
    /// HPKE encapsulated key — 65 raw bytes for DHKEM(P-256).
    let enc: Data
    /// AEAD ciphertext with the 16-byte AES-GCM tag appended.
    let ct: Data

    /// Read the envelope out of an APNs `userInfo` dictionary.
    ///
    /// Returns `nil` for anything that is not a well-formed v1 envelope — a junk push from a
    /// misbehaving relay, a `content-available` ping, or a future version. The caller renders
    /// all of those identically (the unverified notice), so this deliberately does not
    /// distinguish "absent" from "malformed": neither is content this device can vouch for.
    static func parse(userInfo: [AnyHashable: Any]) -> NotifyEnvelope? {
        guard let block = userInfo["ezpds"] as? [String: Any],
              let version = block["v"] as? Int,
              version == supportedVersion,
              let kid = block["kid"] as? Int,
              let encText = block["enc"] as? String,
              let ctText = block["ct"] as? String,
              let enc = Data(base64URLEncoded: encText),
              let ct = Data(base64URLEncoded: ctText),
              !enc.isEmpty, !ct.isEmpty
        else { return nil }

        return NotifyEnvelope(version: version, kid: kid, enc: enc, ct: ct)
    }
}

/// The decrypted plaintext a Custos instance seals.
///
/// Wire shape: `{ "type": …, "title": …, "body": …, "data": { … }, "pad": "…" }`. `pad` is
/// dropped on the floor here — its whole job was to make the *serialized APNs request* land
/// on a padding bucket, which is finished by the time these bytes exist.
struct NotifyPayload: Equatable, Decodable {
    let type: String
    let title: String
    let body: String

    /// Decode sealed plaintext, rejecting a payload with nothing to render.
    ///
    /// An empty title *and* body would produce a banner indistinguishable from a silent
    /// delivery failure, so it is treated as a malformed payload and rendered as the
    /// unverified notice instead — the extension's one rule is that it never shows something
    /// it cannot stand behind.
    static func decode(_ plaintext: Data) -> NotifyPayload? {
        guard let payload = try? JSONDecoder().decode(NotifyPayload.self, from: plaintext),
              !(payload.title.isEmpty && payload.body.isEmpty)
        else { return nil }
        return payload
    }
}

// MARK: - base64url

extension Data {
    /// Decode unpadded base64url — the encoding every binary field in the envelope uses
    /// (`URL_SAFE_NO_PAD` on the Rust side). Foundation only speaks standard base64 with
    /// padding, so translate the alphabet and re-pad.
    init?(base64URLEncoded input: String) {
        var text = input.replacingOccurrences(of: "-", with: "+")
            .replacingOccurrences(of: "_", with: "/")
        let remainder = text.count % 4
        if remainder == 1 {
            // 4n+1 is not a length any base64 encoding can produce; padding it would
            // manufacture a decodable string out of corrupt input.
            return nil
        }
        if remainder > 0 {
            text += String(repeating: "=", count: 4 - remainder)
        }
        guard let decoded = Data(base64Encoded: text) else { return nil }
        self = decoded
    }
}

// MARK: - did:key

/// Decode a P-256 `did:key` into its raw SEC1 public-key bytes.
///
/// The pinned sender keys arrive from Custos as `did:key:z…` strings and are stored verbatim
/// by the wallet (`notifications.rs`), so the extension has to undo the encoding itself:
/// multibase base58btc (`z` prefix) wrapping the multicodec varint `0x1200` — written
/// little-endian-base128 as `0x80 0x24` — followed by a 33-byte compressed point.
///
/// Returns `nil` for anything that is not exactly that. A sender key this device cannot
/// decode is simply not a candidate; HPKE Auth mode would fail closed on it anyway, so
/// skipping costs nothing and misreading could not gain anything.
enum DidKey {
    /// The multicodec prefix for `p256-pub`, varint-encoded.
    static let p256Prefix: [UInt8] = [0x80, 0x24]
    /// A compressed SEC1 P-256 point: 1 tag byte + 32-byte X.
    static let compressedPointLength = 33

    static func p256PublicKeyBytes(from didKey: String) -> Data? {
        guard didKey.hasPrefix("did:key:z") else { return nil }
        let multibase = String(didKey.dropFirst("did:key:z".count))
        guard let decoded = Base58.decode(multibase),
              decoded.count == p256Prefix.count + compressedPointLength,
              Array(decoded.prefix(p256Prefix.count)) == p256Prefix
        else { return nil }
        return Data(decoded.dropFirst(p256Prefix.count))
    }
}

/// base58btc, the one multibase alphabet `did:key` uses.
///
/// Hand-rolled because the extension links nothing but system frameworks: a Swift package
/// dependency in an NSE is a second supply chain in the one target that runs on a locked
/// screen, for ~30 lines of long division.
enum Base58 {
    private static let alphabet = Array("REDACTED".utf8)

    static func decode(_ input: String) -> [UInt8]? {
        var bytes: [UInt8] = [0]
        for character in input.utf8 {
            guard let value = alphabet.firstIndex(of: character) else { return nil }
            var carry = value
            for index in bytes.indices.reversed() {
                carry += 58 * Int(bytes[index])
                bytes[index] = UInt8(carry & 0xff)
                carry >>= 8
            }
            while carry > 0 {
                bytes.insert(UInt8(carry & 0xff), at: 0)
                carry >>= 8
            }
        }
        // Every leading '1' encodes one leading zero byte, which the arithmetic above cannot
        // recover (it carries no magnitude).
        var leadingZeros = 0
        for character in input.utf8 {
            guard character == alphabet[0] else { break }
            leadingZeros += 1
        }
        // Drop the seed byte and any zeros the long division introduced, then restore the
        // encoded ones.
        let significant = Array(bytes.drop(while: { $0 == 0 }))
        return Array(repeating: 0, count: leadingZeros) + significant
    }
}

// The extension's half of the shared Keychain contract MM-419 established.
//
// Every constant here is a copy of one in `apps/identity-wallet/src-tauri/src/keychain.rs`
// and `notifications.rs`, because the two processes are separate bundles that can only agree
// by both spelling the same strings. Nothing else may be added: the app writes, the
// extension reads, and the single exception (the breadcrumb log) is written by both.
//
// # Why no `kSecAttrAccessGroup` anywhere below
//
// Exactly the wallet's stance, and for the same reason. Naming a group means discovering the
// team's `AppIdentifierPrefix` at runtime, which adds a failure mode to the one code path
// that must work on a locked screen. Instead the entitlement's *shape* carries the contract:
// `$(AppIdentifierPrefix)org.obsign.shared` is listed FIRST in both bundles' entitlements, so
// an unqualified write lands there and an unqualified read searches every entitled group.
// `just bundle-identity-check` and `just ios-template-check` enforce the ordering.

import Foundation
import Security

enum NotifyKeychain {
    /// `keychain::SERVICE`. Changing it orphans every item the app ever wrote.
    static let service = "ezpds-identity-wallet"

    /// `notifications::NOTIFICATION_KEY_ACCOUNT` — the raw 32-byte P-256 scalar.
    static let notificationKeyAccount = "notification-key-priv"
    /// `notifications::PINNED_SENDER_KEYS_ACCOUNT` — the per-host pin document.
    static let pinnedSenderKeysAccount = "notification-sender-keys"
    /// `notifications::FAILURE_LOG_ACCOUNT` — the breadcrumbs Settings surfaces.
    static let failureLogAccount = "notification-failures"

    /// Read a device-local generic password.
    ///
    /// Returns `nil` for a missing item *and* for a locked Keychain (`errSecInteractionNotAllowed`,
    /// what a push arriving before the first unlock after a reboot sees). The caller renders both
    /// as the unverified notice, so the distinction would buy nothing here — it is drawn in the
    /// breadcrumb instead, where it is the difference between "reboot, this will fix itself" and
    /// "your keys and your server's disagree".
    static func read(account: String) -> Data? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne,
        ]
        var item: CFTypeRef?
        guard SecItemCopyMatching(query as CFDictionary, &item) == errSecSuccess else { return nil }
        return item as? Data
    }

    /// Write a device-local generic password under `kSecAttrAccessibleAfterFirstUnlock`.
    ///
    /// Delete-then-add, matching `keychain::store_item_after_first_unlock` exactly:
    /// `SecItemUpdate` cannot change an existing item's protection class, so an update would
    /// silently inherit whatever class the first writer set — and on this account the class is
    /// the whole contract, since a breadcrumb about a locked-screen failure is itself written
    /// on a locked screen.
    @discardableResult
    static func write(account: String, data: Data) -> Bool {
        let identity: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
        ]
        SecItemDelete(identity as CFDictionary)

        var attributes = identity
        attributes[kSecValueData as String] = data
        attributes[kSecAttrAccessible as String] = kSecAttrAccessibleAfterFirstUnlock
        return SecItemAdd(attributes as CFDictionary, nil) == errSecSuccess
    }
}

/// One published sender key, mirroring `notifications::SenderKey`.
struct PinnedSenderKey: Decodable, Equatable {
    let kid: Int
    let publicKey: String
}

/// The pin document, mirroring `notifications::PinnedSenderKeys`.
struct PinnedSenderKeys: Decodable {
    static let supportedVersion = 1

    let version: Int
    /// Hosting server → that server's published set.
    let hosts: [String: [PinnedSenderKey]]

    /// Every key published under `kid`, across every host this device has pinned against.
    ///
    /// A flat list on purpose. `kid` is an autoincrement column on *one* instance, so a wallet
    /// holding identities on two servers will hold two unrelated keys under `kid: 1` — and the
    /// push that arrives carries no DID, no handle, and no host, because naming one would give
    /// the relay and Apple exactly the metadata this design exists to withhold. So the
    /// extension cannot know which host sent it, and tries all of them. That costs nothing and
    /// risks nothing: HPKE Auth mode either authenticates against a given sender key or it
    /// does not, so a wrong candidate fails closed and the next is tried.
    func candidates(for kid: Int) -> [String] {
        hosts.values.flatMap { $0 }.filter { $0.kid == kid }.map(\.publicKey)
    }

    /// Parse the stored document, treating an unreadable or foreign-version one as empty.
    ///
    /// **Fail-open**, exactly as `notifications::load_pins` is, and for the same reason: this
    /// holds public keys the server hands back on the next contact. Refusing to read it would
    /// forfeit nothing an attacker wants and cost the user the notification in front of them.
    /// The safety property lives in HPKE, not here — an empty candidate set renders the
    /// unverified notice, which is the correct outcome.
    static func parse(_ raw: Data?) -> PinnedSenderKeys {
        guard let raw,
              let decoded = try? JSONDecoder().decode(PinnedSenderKeys.self, from: raw),
              decoded.version == supportedVersion
        else { return PinnedSenderKeys(version: supportedVersion, hosts: [:]) }
        return decoded
    }
}

// The diagnostic trail behind the unverified notice.
//
// iOS will not let a Notification Service Extension suppress an alert push, so a payload the
// device cannot verify still produces a banner. The banner says so honestly — but on its own
// it is a mystery: a user seeing "couldn't verify" three days running has no way to tell a
// key desync from a relay sending junk. These breadcrumbs are what turns that into something
// Settings can state, and they are the *only* thing the extension leaves behind.
//
// They are written to the shared Keychain rather than an app-group container. The group the
// extension already needs (`org.obsign.shared`) requires no Apple Developer portal work,
// where an app group would be a second entitlement on both bundles; and the protection class
// is the same one the notification key already carries, so a breadcrumb is writable in
// exactly the moments a decryption is attemptable. The one case that buys: a push arriving
// before the first unlock after a reboot leaves no breadcrumb — but that state repairs itself
// the moment the user unlocks, and is the least diagnostic-worthy of the failures.

import Foundation

/// Why a payload could not be rendered as authentic. Shared vocabulary with
/// `notifications::NotificationFailureReason` on the Rust side — the app maps these onto the
/// sentences Settings shows, so a new case here needs one there.
enum NotifyFailureReason: String {
    /// No `ezpds` block, or one this version cannot parse. What a junk push from a
    /// misbehaving relay looks like — the relay holds the APNs key and can always send noise.
    case malformedPayload = "MALFORMED_PAYLOAD"
    /// The notification key or the pin document could not be read: either nothing is
    /// registered yet, or the Keychain is locked before the first unlock after a reboot.
    case keysUnavailable = "KEYS_UNAVAILABLE"
    /// No pinned sender key carries the envelope's `kid`. The key-desync signature: the
    /// instance rotated and this device has not re-pinned since.
    case unknownKid = "UNKNOWN_KID"
    /// Candidates existed and every one of them failed to open the payload. HPKE Auth mode
    /// failing closed — a forged or corrupted ciphertext, or a genuinely stale pin.
    case openFailed = "OPEN_FAILED"
    /// The payload opened — so it *was* authentic — but carried nothing renderable.
    case malformedPlaintext = "MALFORMED_PLAINTEXT"
}

/// One recorded failure.
struct NotifyFailure: Codable, Equatable {
    let at: String
    let reason: String
    /// The envelope's `kid`, where there was a parseable envelope to read one from.
    let kid: Int?
}

/// The stored log: newest first, bounded.
struct NotifyFailureLog: Codable {
    static let supportedVersion = 1
    /// Enough to show a pattern ("five in the last day"), small enough that the whole log
    /// stays a single modest Keychain item. Older entries answer no question the newer ones
    /// do not.
    static let capacity = 20

    var version: Int
    var failures: [NotifyFailure]

    static let empty = NotifyFailureLog(version: supportedVersion, failures: [])

    /// Read the log, treating anything unreadable as empty.
    ///
    /// Fail-open like the pin store: this is a diagnostic trail, and refusing to append to a
    /// damaged one would lose the very breadcrumb that is being recorded right now.
    static func parse(_ raw: Data?) -> NotifyFailureLog {
        guard let raw,
              let decoded = try? JSONDecoder().decode(NotifyFailureLog.self, from: raw),
              decoded.version == supportedVersion
        else { return .empty }
        return decoded
    }

    /// Prepend `failure`, dropping the oldest beyond [`capacity`]. Pure, so the trimming rule
    /// is testable without a Keychain.
    func appending(_ failure: NotifyFailure) -> NotifyFailureLog {
        NotifyFailureLog(
            version: Self.supportedVersion,
            failures: Array(([failure] + failures).prefix(Self.capacity))
        )
    }
}

enum NotifyBreadcrumbs {
    /// Record one failure, best effort.
    ///
    /// Every outcome is swallowed. The extension has one job left at this point — putting an
    /// honest notice on screen before iOS's timeout — and a Keychain that will not take a
    /// diagnostic must not be allowed to cost the user that. A lost breadcrumb is a lost
    /// breadcrumb; a lost `contentHandler` call is the placeholder text shown instead.
    static func record(_ reason: NotifyFailureReason, kid: Int?, now: Date = Date()) {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime]
        let failure = NotifyFailure(
            at: formatter.string(from: now),
            reason: reason.rawValue,
            kid: kid
        )

        let log = NotifyFailureLog
            .parse(NotifyKeychain.read(account: NotifyKeychain.failureLogAccount))
            .appending(failure)

        guard let encoded = try? JSONEncoder().encode(log) else { return }
        NotifyKeychain.write(account: NotifyKeychain.failureLogAccount, data: encoded)
    }
}

// The CryptoKit side of the HPKE envelope `crates/crypto/src/hpke.rs` seals.
//
// The ciphersuite is not chosen here, it is *forced*: CryptoKit ships exactly one P-256 HPKE
// suite, `P256_SHA256_AES_GCM_256`, and the Rust side is pinned to match it. That is why the
// wire format has no negotiation and no downgrade lattice — there is nothing to negotiate
// with. `HPKE.Recipient`'s auth-mode initializer is also why both apps deploy at iOS 17: the
// API does not exist before it.
//
// Cross-implementation agreement is verified by NotifyFixtureTests, which opens the golden
// vectors in `crates/crypto/tests/fixtures/notify/` — the whole reason those fixtures were
// generated, since RFC 9180's appendix carries no vector for this exact suite.

import CryptoKit
import Foundation

enum NotifyCrypto {
    /// RFC 9180 `info` for v1 — `crypto::NOTIFY_INFO`. Bound into the key schedule, so a
    /// payload sealed for a different protocol version cannot open here even with the right
    /// keys. This is the version binding; the envelope's `v` is a routing hint, not a trust
    /// decision.
    static let info = Data("ezpds/notify/1".utf8)
    /// RFC 9180 `aad` for v1 — `crypto::NOTIFY_AAD`. Empty: everything a receiver must trust
    /// already rides in `info`.
    static let aad = Data()

    static let ciphersuite = HPKE.Ciphersuite.P256_SHA256_AES_GCM_256

    /// Open a sealed payload, authenticated as `senderPublicKey`.
    ///
    /// `recipientPrivateKey` is the raw 32-byte scalar out of the Keychain;
    /// `senderPublicKey` is SEC1 bytes, compressed (33, what a `did:key` decodes to) or
    /// uncompressed (65, what the golden fixtures store).
    ///
    /// Returns `nil` on any failure — a malformed key, a wrong sender, a corrupted
    /// ciphertext. The caller does not act on the distinction: in Auth mode "this did not
    /// open" and "this was not sent by the key you pinned" are the same verdict, which is
    /// exactly the property that makes the relay a courier rather than an author.
    static func open(
        recipientPrivateKey: Data,
        senderPublicKey: Data,
        encapsulatedKey: Data,
        ciphertext: Data
    ) -> Data? {
        guard let privateKey = try? P256.KeyAgreement.PrivateKey(rawRepresentation: recipientPrivateKey),
              let publicKey = senderKey(from: senderPublicKey)
        else { return nil }

        guard let recipient = try? HPKE.Recipient(
            privateKey: privateKey,
            ciphersuite: ciphersuite,
            info: info,
            encapsulatedKey: encapsulatedKey,
            authenticatedBy: publicKey
        ) else { return nil }

        return try? recipient.open(ciphertext, authenticating: aad)
    }

    /// Accept either SEC1 encoding. `did:key` yields the compressed point; the Rust fixtures
    /// pin the uncompressed one, and both must reach the same key.
    private static func senderKey(from bytes: Data) -> P256.KeyAgreement.PublicKey? {
        if let compressed = try? P256.KeyAgreement.PublicKey(compressedRepresentation: bytes) {
            return compressed
        }
        return try? P256.KeyAgreement.PublicKey(x963Representation: bytes)
    }
}

// The Notification Service Extension: the only place a sealed push is ever plaintext.
//
// A Custos instance HPKE-seals a notification to this device's key and hands it to a relay
// that holds the APNs key but no decryption key. The relay and Apple both carry the payload
// as opaque bytes beside a placeholder alert ("Custos / Encrypted notification"), and
// `mutable-content: 1` routes it here for the ~30 seconds iOS allows before it gives up and
// shows the placeholder.
//
// # The constraint that shapes everything below
//
// **An NSE cannot suppress an alert push.** If this code fails, times out, or declines to
// attach content, iOS displays the original payload anyway. So "drop what we cannot verify"
// is not on the menu; the only thing under this extension's control is *what the user reads*.
// The rule is therefore absolute: content that opened under HPKE Auth mode renders as
// content, and everything else renders as the explicit unverified notice. Never a guess,
// never a partial render, never the placeholder passed through as though it were news.
//
// That is what keeps a relay's junk push from being an impersonation. The relay can always
// generate noise — it holds the APNs key — but noise arrives labelled as unverifiable, which
// is detectable spam and grounds for switching relays, not a forged message from your server.

import UserNotifications

/// The decision the extension makes about one payload, split out from the `UNNotification`
/// machinery so every branch is reachable from a test.
enum NotifyOutcome: Equatable {
    case rendered(NotifyPayload)
    case unverified(NotifyFailureReason, kid: Int?)
}

enum NotifyResolver {
    /// The user-visible copy for a payload this device cannot vouch for.
    ///
    /// Deliberately says what happened and nothing more. It names no sender ("from your
    /// Custos instance" is a category, not a claim about which one), states no cause the
    /// extension cannot know, and offers no action — the actionable version of this lives in
    /// Settings, where the breadcrumbs can say whether it happened once or twenty times.
    static let unverifiedTitle = "Unverified notification"
    static let unverifiedBody = "Couldn't verify a notification from your Custos instance."

    /// Resolve an APNs `userInfo` into what should be shown.
    ///
    /// Pure over its inputs — the Keychain reads happen in the caller — so the whole failure
    /// ladder is exercisable on a simulator with no push and no registered key.
    static func resolve(
        userInfo: [AnyHashable: Any],
        recipientPrivateKey: Data?,
        pins: PinnedSenderKeys
    ) -> NotifyOutcome {
        guard let envelope = NotifyEnvelope.parse(userInfo: userInfo) else {
            return .unverified(.malformedPayload, kid: nil)
        }
        guard let recipientPrivateKey else {
            return .unverified(.keysUnavailable, kid: envelope.kid)
        }

        let candidates = pins.candidates(for: envelope.kid)
        guard !candidates.isEmpty else {
            return .unverified(.unknownKid, kid: envelope.kid)
        }

        // Try every key pinned under this `kid`. See `PinnedSenderKeys.candidates` for why
        // there can be more than one; Auth mode makes a wrong guess free.
        for didKey in candidates {
            guard let senderBytes = DidKey.p256PublicKeyBytes(from: didKey) else { continue }
            guard let plaintext = NotifyCrypto.open(
                recipientPrivateKey: recipientPrivateKey,
                senderPublicKey: senderBytes,
                encapsulatedKey: envelope.enc,
                ciphertext: envelope.ct
            ) else { continue }

            // Past this point the payload is authenticated: only a holder of a pinned sender
            // private key could have produced it. A body we cannot parse is therefore our own
            // bug or a version skew, not an attack — but it still cannot be rendered as
            // content, because there is no content to render.
            guard let payload = NotifyPayload.decode(plaintext) else {
                return .unverified(.malformedPlaintext, kid: envelope.kid)
            }
            return .rendered(payload)
        }

        return .unverified(.openFailed, kid: envelope.kid)
    }
}

final class NotificationService: UNNotificationServiceExtension {
    private var contentHandler: ((UNNotificationContent) -> Void)?
    private var bestAttempt: UNMutableNotificationContent?

    override func didReceive(
        _ request: UNNotificationRequest,
        withContentHandler contentHandler: @escaping (UNNotificationContent) -> Void
    ) {
        self.contentHandler = contentHandler
        guard let content = request.content.mutableCopy() as? UNMutableNotificationContent else {
            contentHandler(request.content)
            return
        }
        bestAttempt = content

        let outcome = NotifyResolver.resolve(
            userInfo: request.content.userInfo,
            recipientPrivateKey: NotifyKeychain.read(
                account: NotifyKeychain.notificationKeyAccount
            ),
            pins: PinnedSenderKeys.parse(
                NotifyKeychain.read(account: NotifyKeychain.pinnedSenderKeysAccount)
            )
        )

        switch outcome {
        case let .rendered(payload):
            content.title = payload.title
            content.body = payload.body
        case let .unverified(reason, kid):
            content.title = NotifyResolver.unverifiedTitle
            content.body = NotifyResolver.unverifiedBody
            NotifyBreadcrumbs.record(reason, kid: kid)
        }

        // The sealed block has served its purpose and must not ride along into the delivered
        // notification, where the app (and anything reading `UNUserNotificationCenter`'s
        // delivered list) would see ciphertext it has no use for.
        content.userInfo.removeValue(forKey: "ezpds")

        contentHandler(content)
    }

    /// iOS is about to give up on us.
    ///
    /// Whatever is in `bestAttempt` is delivered; if we never got as far as writing the
    /// unverified notice into it, that content is still the relay's placeholder. Say so
    /// rather than let a timeout be the one path where unverified text renders as though it
    /// were the server's — the extension's rule does not get an exception for running late.
    override func serviceExtensionTimeWillExpire() {
        guard let contentHandler, let bestAttempt else { return }
        if bestAttempt.title != NotifyResolver.unverifiedTitle,
           bestAttempt.userInfo["ezpds"] != nil {
            bestAttempt.title = NotifyResolver.unverifiedTitle
            bestAttempt.body = NotifyResolver.unverifiedBody
        }
        contentHandler(bestAttempt)
    }
}

// The cross-implementation check the golden fixtures were generated for.
//
// `crates/crypto/tests/fixtures/notify/hpke-notify-v1.json` is sealed by the Rust `hpke`
// crate and opened, here, by CryptoKit. RFC 9180's appendix has no test vector for this exact
// suite (A.3 is AES-128; CryptoKit's only P-256 suite forces AES-256), so nothing else proves
// the two implementations agree on the pinned suite, the `info` string, the empty `aad`, and
// the key encodings. The Rust side asserts these same vectors round-trip in
// `notify_hpke_vectors.rs`; between them, a drift on either side fails a test instead of
// producing devices that silently stop decrypting.
//
// The fixture file is referenced IN PLACE by the XcodeGen template — there is no copy in this
// directory to fall out of date with the crate.
//
// Not run by CI: `ios-pr-check` stops short of xcodebuild (no simulator, no archive), so this
// is a `⌘U` in Xcode or `xcodebuild test`. That is the same footing as the on-device demo the
// issue's acceptance names, and the reason the pure logic below is also covered by tests that
// need no crypto at all.

import CryptoKit
import XCTest

@testable import NotificationService

private struct NotifyVector: Decodable {
    let comment: String
    let senderPublicKeyBase64: String
    let recipientPrivateKeyBytes: [UInt8]
    let recipientPublicKeyBase64: String
    let plaintextBase64: String
    let encBase64: String
    let ctBase64: String
}

final class NotifyFixtureTests: XCTestCase {
    private func vectors() throws -> [NotifyVector] {
        let bundle = Bundle(for: type(of: self))
        let url = try XCTUnwrap(
            bundle.url(forResource: "hpke-notify-v1", withExtension: "json"),
            "the crates/crypto fixture must be bundled as a test resource"
        )
        return try JSONDecoder().decode([NotifyVector].self, from: Data(contentsOf: url))
    }

    private func b64(_ text: String) throws -> Data {
        try XCTUnwrap(Data(base64URLEncoded: text), "fixture value must be base64url")
    }

    /// The interop assertion: every payload Rust sealed, CryptoKit opens to the same bytes.
    func testCryptoKitOpensTheRustGoldenVectors() throws {
        let vectors = try vectors()
        XCTAssertFalse(vectors.isEmpty, "an empty fixture file would pass vacuously")

        for vector in vectors {
            let opened = NotifyCrypto.open(
                recipientPrivateKey: Data(vector.recipientPrivateKeyBytes),
                senderPublicKey: try b64(vector.senderPublicKeyBase64),
                encapsulatedKey: try b64(vector.encBase64),
                ciphertext: try b64(vector.ctBase64)
            )
            XCTAssertEqual(try b64(vector.plaintextBase64), opened, vector.comment)
        }
    }

    /// Auth mode's whole point: a payload opened with the wrong sender key does not open at
    /// all. This is what makes a relay a courier — it can drop and duplicate, but nothing it
    /// fabricates ever renders as content from the user's own instance.
    func testAWrongSenderKeyFailsClosed() throws {
        for vector in try vectors() {
            // Any other valid P-256 public key. The recipient's own is guaranteed to be one,
            // and guaranteed not to be the sender's.
            let wrongSender = try b64(vector.recipientPublicKeyBase64)
            XCTAssertNil(
                NotifyCrypto.open(
                    recipientPrivateKey: Data(vector.recipientPrivateKeyBytes),
                    senderPublicKey: wrongSender,
                    encapsulatedKey: try b64(vector.encBase64),
                    ciphertext: try b64(vector.ctBase64)
                ),
                vector.comment
            )
        }
    }

    /// A flipped ciphertext byte is an AEAD failure, not a partial plaintext.
    func testATamperedCiphertextDoesNotOpen() throws {
        for vector in try vectors() {
            var ciphertext = try b64(vector.ctBase64)
            ciphertext[0] ^= 0x01
            XCTAssertNil(
                NotifyCrypto.open(
                    recipientPrivateKey: Data(vector.recipientPrivateKeyBytes),
                    senderPublicKey: try b64(vector.senderPublicKeyBase64),
                    encapsulatedKey: try b64(vector.encBase64),
                    ciphertext: ciphertext
                ),
                vector.comment
            )
        }
    }

    /// The fixtures' plaintext is the wire payload the extension renders, not opaque bytes —
    /// so the decode step is part of what interop means.
    func testOpenedFixturesDecodeAsRenderablePayloads() throws {
        for vector in try vectors() {
            let plaintext = try b64(vector.plaintextBase64)
            let payload = try XCTUnwrap(NotifyPayload.decode(plaintext), vector.comment)
            XCTAssertFalse(payload.title.isEmpty && payload.body.isEmpty)
        }
    }

    /// `info` carries the version binding, so a payload sealed for another protocol version
    /// cannot open here even with every key correct.
    func testTheInfoStringIsTheVersionBinding() throws {
        XCTAssertEqual(NotifyCrypto.info, Data("ezpds/notify/1".utf8))
        XCTAssertTrue(NotifyCrypto.aad.isEmpty)
    }
}

// The failure ladder, with no crypto and no Keychain.
//
// Every branch here ends in a banner the user reads, so each one is worth pinning: the
// extension's single rule is that authenticated content renders as content and everything
// else renders as the unverified notice, and these are the cases where that rule could quietly
// erode into "render whatever we managed to parse".

import XCTest

@testable import NotificationService

private func envelope(v: Int = 1, kid: Int = 1, enc: String = "AQID", ct: String = "BAUG") -> [AnyHashable: Any] {
    ["aps": ["alert": ["title": "Custos", "body": "Encrypted notification"]],
     "ezpds": ["v": v, "kid": kid, "enc": enc, "ct": ct]]
}

final class NotifyEnvelopeTests: XCTestCase {
    func testAWellFormedEnvelopeParses() throws {
        let parsed = try XCTUnwrap(NotifyEnvelope.parse(userInfo: envelope()))
        XCTAssertEqual(parsed.kid, 1)
        XCTAssertEqual(parsed.enc, Data([0x01, 0x02, 0x03]))
        XCTAssertEqual(parsed.ct, Data([0x04, 0x05, 0x06]))
    }

    /// A push with no `ezpds` block at all — what a relay sending junk, or a future
    /// content-free ping, looks like.
    func testAPushWithoutTheEnvelopeIsRejected() {
        XCTAssertNil(NotifyEnvelope.parse(userInfo: ["aps": ["alert": "hello"]]))
    }

    /// A newer instance sealing for a newer extension. Guessing at it would be the one way
    /// unverifiable bytes could reach the screen as content.
    func testAFutureVersionIsRejectedRatherThanGuessed() {
        XCTAssertNil(NotifyEnvelope.parse(userInfo: envelope(v: 2)))
    }

    func testEmptyOrUndecodableFieldsAreRejected() {
        XCTAssertNil(NotifyEnvelope.parse(userInfo: envelope(enc: "")))
        XCTAssertNil(NotifyEnvelope.parse(userInfo: envelope(ct: "!!!not base64!!!")))
        // 4n+1 is a length no base64 encoding can produce; re-padding it would manufacture a
        // decodable string out of corrupt input.
        XCTAssertNil(NotifyEnvelope.parse(userInfo: envelope(enc: "AAAAA")))
    }

    func testBase64UrlDecodesTheAlphabetTheRustSideEmits() {
        // URL_SAFE_NO_PAD: '-' and '_' for '+' and '/', and no '=' padding.
        XCTAssertEqual(Data(base64URLEncoded: "-_8"), Data([0xfb, 0xff]))
        XCTAssertEqual(Data(base64URLEncoded: "AQ"), Data([0x01]))
    }
}

final class DidKeyTests: XCTestCase {
    /// A real P-256 did:key. The pinned sender keys arrive in exactly this form, so a
    /// regression here silently empties every candidate set and turns every push into the
    /// unverified notice.
    private let sample = "did:key:REDACTED"

    func testAP256DidKeyDecodesToACompressedPoint() throws {
        let bytes = try XCTUnwrap(DidKey.p256PublicKeyBytes(from: sample))
        XCTAssertEqual(bytes.count, DidKey.compressedPointLength)
        XCTAssertTrue(bytes[0] == 0x02 || bytes[0] == 0x03, "compressed SEC1 parity tag")
    }

    func testNonP256AndMalformedKeysAreRejected() {
        // An Ed25519 did:key — right shape, wrong multicodec.
        XCTAssertNil(DidKey.p256PublicKeyBytes(
            from: "did:key:REDACTED"
        ))
        XCTAssertNil(DidKey.p256PublicKeyBytes(from: "did:key:zNOTBASE58!!!"))
        XCTAssertNil(DidKey.p256PublicKeyBytes(from: "did:plc:abc123"))
        XCTAssertNil(DidKey.p256PublicKeyBytes(from: ""))
    }

    func testBase58PreservesLeadingZeroBytes() {
        // '1' is base58's zero digit; the long division carries no magnitude for it, so the
        // leading zeros have to be restored explicitly or every multicodec prefix shifts.
        XCTAssertEqual(Base58.decode("11"), [0x00, 0x00])
        XCTAssertEqual(Base58.decode("12"), [0x00, 0x01])
    }
}

final class NotifyResolverTests: XCTestCase {
    private let key = Data(repeating: 0x01, count: 32)

    private func pins(_ entries: [(Int, String)]) -> PinnedSenderKeys {
        PinnedSenderKeys(
            version: 1,
            hosts: ["https://pds.example.com": entries.map { PinnedSenderKey(kid: $0.0, publicKey: $0.1) }]
        )
    }

    func testAJunkPushIsUnverifiedRatherThanRendered() {
        let outcome = NotifyResolver.resolve(
            userInfo: ["aps": ["alert": "Buy crypto now"]],
            recipientPrivateKey: key,
            pins: pins([])
        )
        XCTAssertEqual(outcome, .unverified(.malformedPayload, kid: nil))
    }

    /// The post-reboot locked Keychain, and the never-registered device, reach the same
    /// place — the extension cannot tell them apart and must not pretend to.
    func testAnUnreadableKeyIsUnverified() {
        let outcome = NotifyResolver.resolve(
            userInfo: envelope(kid: 3),
            recipientPrivateKey: nil,
            pins: pins([(3, "did:key:REDACTED")])
        )
        XCTAssertEqual(outcome, .unverified(.keysUnavailable, kid: 3))
    }

    /// The key-desync signature: the instance rotated and this device has not re-pinned. It
    /// is recorded distinctly because it is the one failure Settings can give real advice
    /// about — open the app so it re-pins.
    func testAnUnpinnedKidIsRecordedAsItsOwnFailure() {
        let outcome = NotifyResolver.resolve(
            userInfo: envelope(kid: 9),
            recipientPrivateKey: key,
            pins: pins([(1, "did:key:REDACTED")])
        )
        XCTAssertEqual(outcome, .unverified(.unknownKid, kid: 9))
    }

    /// Candidates existed and none opened it. Reached here with junk ciphertext, which is
    /// precisely the replayed-junk payload the acceptance criteria name.
    func testCandidatesThatAllFailToOpenAreUnverified() {
        let outcome = NotifyResolver.resolve(
            userInfo: envelope(kid: 1),
            recipientPrivateKey: key,
            pins: pins([(1, "did:key:REDACTED")])
        )
        XCTAssertEqual(outcome, .unverified(.openFailed, kid: 1))
    }

    /// An undecodable `did:key` is skipped, not fatal — but with nothing left to try the
    /// verdict is still "did not open", never a render.
    func testAnUndecodableCandidateIsSkipped() {
        let outcome = NotifyResolver.resolve(
            userInfo: envelope(kid: 1),
            recipientPrivateKey: key,
            pins: pins([(1, "did:key:zGARBAGE"), (1, "did:key:zAlsoGarbage")])
        )
        XCTAssertEqual(outcome, .unverified(.openFailed, kid: 1))
    }

    func testTheUnverifiedNoticeNeverImpersonatesContent() {
        XCTAssertTrue(NotifyResolver.unverifiedBody.contains("Couldn't verify"))
        XCTAssertNotEqual(NotifyResolver.unverifiedTitle, "Custos")
    }
}

final class NotifyBreadcrumbTests: XCTestCase {
    func testTheLogIsNewestFirstAndBounded() {
        var log = NotifyFailureLog.empty
        for index in 0..<(NotifyFailureLog.capacity + 5) {
            log = log.appending(NotifyFailure(at: "t\(index)", reason: "OPEN_FAILED", kid: index))
        }
        XCTAssertEqual(log.failures.count, NotifyFailureLog.capacity)
        XCTAssertEqual(log.failures.first?.kid, NotifyFailureLog.capacity + 4, "newest first")
        XCTAssertEqual(log.failures.last?.kid, 5, "the oldest entries are the ones dropped")
    }

    /// Fail-open, like the pin store: a damaged log must not cost the user the breadcrumb
    /// being recorded right now.
    func testACorruptOrForeignVersionLogReadsAsEmpty() {
        XCTAssertTrue(NotifyFailureLog.parse(Data("{not json".utf8)).failures.isEmpty)
        XCTAssertTrue(NotifyFailureLog.parse(nil).failures.isEmpty)
        let foreign = Data(#"{"version":99,"failures":[{"at":"t","reason":"OPEN_FAILED","kid":1}]}"#.utf8)
        XCTAssertTrue(NotifyFailureLog.parse(foreign).failures.isEmpty)
    }
}

final class PinnedSenderKeysTests: XCTestCase {
    /// Two instances both start their `kid` sequence at 1, and the push names no host — so
    /// every key under the incoming `kid` is a candidate, across every pinned host.
    func testCandidatesSpanEveryHost() {
        let pins = PinnedSenderKeys(version: 1, hosts: [
            "https://a.example.com": [PinnedSenderKey(kid: 1, publicKey: "did:key:zA")],
            "https://b.example.com": [PinnedSenderKey(kid: 1, publicKey: "did:key:zB"),
                                      PinnedSenderKey(kid: 2, publicKey: "did:key:zC")],
        ])
        XCTAssertEqual(Set(pins.candidates(for: 1)), ["did:key:zA", "did:key:zB"])
        XCTAssertEqual(pins.candidates(for: 2), ["did:key:zC"])
        XCTAssertTrue(pins.candidates(for: 3).isEmpty)
    }

    func testACorruptPinDocumentReadsAsEmpty() {
        XCTAssertTrue(PinnedSenderKeys.parse(Data("{nope".utf8)).hosts.isEmpty)
        XCTAssertTrue(PinnedSenderKeys.parse(nil).hosts.isEmpty)
    }
}

