1	/**
2	 * The `window.__harness` runtime control surface for the wallet harness.
3	 *
4	 * This is what an agent (or a human) drives from the browser console to script the
5	 * fake: switch scenario presets, inject a one-shot typed command failure, deliver a
6	 * Tauri event to live `listen()` subscribers, and read a snapshot of the fake store.
7	 *
8	 * `emit` routes through Tauri's real `@tauri-apps/api/event` `emit()` — which, under
9	 * `mockIPC(..., { shouldMockEvents: true })`, is delivered to the app's live listeners.
10	 * So `window.__harness.emit('auth_ready')` exercises the exact `listen('auth_ready')`
11	 * path the OAuth deep-link return would (browser-harness.AC2.4).
12	 */
13	import { emit } from '@tauri-apps/api/event';
14	import { buildScenario, scenarios } from './scenarios';
15	import type { WalletState } from './state';
16	
17	const SCENARIO_KEY = 'ezpds-harness-scenario';
18	
19	/** The console-facing control API attached to `window.__harness`. */
20	export interface HarnessControl {
21	  /** The active harness mode. */
22	  readonly mode: 'fake' | 'proxy';
23	  /** The names of every available scenario preset. */
24	  readonly scenarios: string[];
25	  /**
26	   * Switch to a named scenario preset. By default persists the choice and reloads so
27	   * every screen re-renders from the new state; pass `{ reload: false }` to reseed the
28	   * live store in place without a reload (the next navigation/mount re-fetches).
29	   */
30	  scenario(name: string, opts?: { reload?: boolean }): void;
31	  /**
32	   * Make the NEXT invocation of `command` reject with `error` (a typed IPC error shape,
33	   * e.g. `{ code: 'EXPIRED_CODE' }`). One-shot: consumed by the next call.
34	   */
35	  failNext(command: string, error: unknown): void;
36	  /** Deliver a Tauri event to live `listen()` subscribers. */
37	  emit(event: string, payload?: unknown): Promise<void>;
38	  /** A deep-cloned, read-only snapshot of the current fake store. */
39	  state(): WalletState;
40	}
41	
42	/** Context the control surface manipulates; owned by `install.ts`. */
43	export interface ControlContext {
44	  state: WalletState;
45	  failNext: Map<string, unknown>;
46	  replaceState: (next: WalletState) => void;
47	  mode: 'fake' | 'proxy';
48	}
49	
50	export function createControl(ctx: ControlContext): HarnessControl {
51	  return {
52	    mode: ctx.mode,
53	    scenarios: Object.keys(scenarios),
54	    scenario(name, opts) {
55	      try {
56	        sessionStorage.setItem(SCENARIO_KEY, name);
57	      } catch {
58	        // sessionStorage may be unavailable; the in-place path below still works.
59	      }
60	      if (opts?.reload === false) {
61	        ctx.replaceState(buildScenario(name));
62	      } else {
63	        location.reload();
64	      }
65	    },
66	    failNext(command, error) {
67	      ctx.failNext.set(command, error);
68	    },
69	    emit(event, payload) {
70	      return emit(event, payload);
71	    },
72	    state() {
73	      return structuredClone(ctx.state);
74	    },
75	  };
76	}
77	
78	/** The scenario to seed on install: a sticky sessionStorage choice, else the env/default. */
79	export function initialScenario(fallback: string): string {
80	  try {
81	    const stored = sessionStorage.getItem(SCENARIO_KEY);
82	    if (stored) return stored;
83	  } catch {
84	    // ignore — fall through to the fallback
85	  }
86	  return fallback;
87	}
